source_edits.find:
{
  name: "list_issues",
  description: "Browse issues filtered by status and/or assignee. Use for structured listing; use search_issues to find issues by text in title or body, and get_issue for one known ID. Returns at most 50 issues unless limit is set. Comments are included by default, so set include_comments=false for smaller responses.",
  params: {
    status: z.string().optional().describe("Filter by issue status. One of: open, in_progress, blocked, closed. Any other value returns an error. Omit to include all statuses."),
    assignee: z.string().optional(),
    include_comments: z.boolean().optional(),
    limit: z.number().optional(),
  },
}

